// src/constants/colors.js — Design tokens for Agro Zenith

const C = {
  // Brand greens
  dark:       "#072412",   // sidebar bg
  bg1:        "#0e3a1c",   // deep green
  bg2:        "#1a6b32",   // primary action green
  light:      "#2e9b4e",   // hover green

  // Backgrounds
  pale:       "#e8f5ee",   // light green tint
  paleDark:   "#d0ead9",
  bg:         "#f0f5f2",   // page background
  white:      "#ffffff",

  // Text
  text:       "#0e1f14",   // primary text
  muted:      "#4d7a5c",   // secondary text

  // Borders
  border:     "#c2d9cb",
  borderDark: "#9cbfad",

  // Semantic
  red:        "#b83232",  redPale:    "#fdf0f0",
  orange:     "#c87010",  orangePale: "#fef6e0",
  blue:       "#1a5e90",  bluePale:   "#e8f2fb",
  amber:      "#c07808",  amberPale:  "#fef4dc",
  purple:     "#6a3db8",  purplePale: "#f2ecfb",

  // Trend indicators
  trendUp:    "#1a7a3a",
  trendDn:    "#b83232",
};

export default C;
